    document.querySelectorAll('[data-cluster-step]').forEach((button,i)=>{button.classList.toggle('active',i===currentStage);button.classList.toggle('done',i<currentStage)});
    document.querySelector('#cluster-step-status').textContent=`第 ${currentStage+1} / ${stages.length} 步`;
    document.querySelector('#cluster-prev-step').disabled=currentStage===0;
    document.querySelector('#cluster-next-step').textContent=currentStage===stages.length-1?'返回第一步':'下一步 →';
